#!/usr/bin/env node

/**
 * Build the lightweight state/territory path data used by the sector explorer.
 *
 * Source: ABS ASGS 2021 State and Territory generalized boundaries.
 * The ArcGIS query asks the ABS service to generalize the geometry to 0.05
 * degrees, then this script removes tiny offshore polygons that cannot be seen
 * at the map's rendered scale and projects the coordinates into a fixed SVG
 * viewBox. The generated file retains the ABS attribution and source URL.
 */

import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';

const sourceUrl =
  'https://geo.abs.gov.au/arcgis/rest/services/ASGS2021/STE/FeatureServer/1/query?' +
  new URLSearchParams({
    where: "state_code_2021<'9'",
    outFields: 'state_code_2021,state_name_2021',
    returnGeometry: 'true',
    outSR: '4326',
    geometryPrecision: '3',
    maxAllowableOffset: '0.05',
    f: 'geojson',
  });

const jurisdictionByCode = {
  '1': 'NSW',
  '2': 'VIC',
  '3': 'QLD',
  '4': 'SA',
  '5': 'WA',
  '6': 'TAS',
  '7': 'NT',
  '8': 'ACT',
};

const labelPoints = {
  NSW: [150.0, -32.4],
  VIC: [145.4, -37.0],
  QLD: [145.0, -21.5],
  SA: [135.2, -30.2],
  WA: [121.2, -25.6],
  TAS: [146.3, -42.0],
  NT: [133.4, -19.4],
  ACT: [149.05, -35.3],
};

const width = 760;
const height = 600;
const bounds = { minLon: 112, maxLon: 154, minLat: -44, maxLat: -9 };

function project([lon, lat]) {
  const x = ((lon - bounds.minLon) / (bounds.maxLon - bounds.minLon)) * width;
  const y = ((bounds.maxLat - lat) / (bounds.maxLat - bounds.minLat)) * height;
  return [Number(x.toFixed(1)), Number(y.toFixed(1))];
}

function ringArea(ring) {
  let area = 0;
  for (let i = 0; i < ring.length - 1; i += 1) {
    area += ring[i][0] * ring[i + 1][1] - ring[i + 1][0] * ring[i][1];
  }
  return Math.abs(area / 2);
}

function pathForRing(ring) {
  const points = ring.map(project);
  return `${points.map(([x, y], index) => `${index ? 'L' : 'M'}${x} ${y}`).join('')}Z`;
}

function geometryToPath(geometry, jurisdiction) {
  const polygons = geometry.type === 'Polygon' ? [geometry.coordinates] : geometry.coordinates;
  return polygons
    .filter((polygon) => jurisdiction === 'ACT' || ringArea(polygon[0]) >= 0.025)
    .flatMap((polygon) => polygon.map(pathForRing))
    .join('');
}

const response = await fetch(sourceUrl);
if (!response.ok) {
  throw new Error(`ABS boundary request failed: ${response.status} ${response.statusText}`);
}

const geojson = await response.json();
if (!Array.isArray(geojson.features) || geojson.features.length !== 8) {
  throw new Error(`Expected 8 state/territory features, received ${geojson.features?.length ?? 0}`);
}

const states = geojson.features
  .map((feature) => {
    const jurisdiction = jurisdictionByCode[feature.properties.state_code_2021];
    const [labelX, labelY] = project(labelPoints[jurisdiction]);
    return {
      jurisdiction,
      name: feature.properties.state_name_2021,
      path: geometryToPath(feature.geometry, jurisdiction),
      labelX,
      labelY,
    };
  })
  .sort((a, b) => Object.keys(jurisdictionByCode).find((key) => jurisdictionByCode[key] === a.jurisdiction) - Object.keys(jurisdictionByCode).find((key) => jurisdictionByCode[key] === b.jurisdiction));

const output = `/* Generated by scripts/build-sector-map.mjs. Do not edit by hand. */\n` +
  `export const AUSTRALIA_MAP_VIEWBOX = ${JSON.stringify({ width, height })} as const;\n\n` +
  `export const AUSTRALIA_MAP_SOURCE = ${JSON.stringify('Australian Bureau of Statistics, ASGS Edition 3 (2021), State and Territory generalized boundaries')} as const;\n` +
  `export const AUSTRALIA_MAP_SOURCE_URL = ${JSON.stringify('https://www.abs.gov.au/statistics/standards/australian-statistical-geography-standard-asgs/edition-3-july-2021-june-2026/access-and-downloads/data-services-and-apis')} as const;\n\n` +
  `export const AUSTRALIA_STATES = ${JSON.stringify(states)} as const;\n`;

const destination = path.resolve(process.cwd(), 'dashboard/lib/australia-map-data.ts');
await writeFile(destination, output, 'utf8');
console.log(`Wrote ${states.length} jurisdictions to ${destination}`);
